-- 0033_purge_demo_placeholders_keep_odoo
-- 0030 already removed the placeholder radar rows. This file removes the three seeded employees
-- and fills salaries from the Venture Foods Odoo export. Posted journals, invoices and stock
-- movements stay, because those tables reject deletion.

create or replace function erp_purge_demo_placeholders() returns integer
language plpgsql as $$
declare
  removed integer;
begin
  delete from hr_attendances as row
  using hr_employees as employee
  where row.tenant_id = employee.tenant_id and row.employee_id = employee.id
    and employee.employee_code in ('EMP-001', 'EMP-002', 'EMP-003');
  delete from hr_leaves as row
  using hr_employees as employee
  where row.tenant_id = employee.tenant_id and row.employee_id = employee.id
    and employee.employee_code in ('EMP-001', 'EMP-002', 'EMP-003');
  delete from hr_appraisals as row
  using hr_employees as employee
  where row.tenant_id = employee.tenant_id and row.employee_id = employee.id
    and employee.employee_code in ('EMP-001', 'EMP-002', 'EMP-003');
  delete from hr_expenses as row
  using hr_employees as employee
  where row.tenant_id = employee.tenant_id and row.employee_id = employee.id
    and employee.employee_code in ('EMP-001', 'EMP-002', 'EMP-003');
  alter table hr_payslips disable trigger hr_payslips_no_delete;
  alter table hr_payroll_runs disable trigger hr_payroll_runs_no_delete;
  delete from hr_payslips as row
  using hr_employees as employee
  where row.tenant_id = employee.tenant_id and row.employee_id = employee.id
    and employee.employee_code in ('EMP-001', 'EMP-002', 'EMP-003');
  delete from hr_payroll_runs as run
  where not exists (
    select 1 from hr_payslips as slip where slip.tenant_id = run.tenant_id and slip.run_id = run.id
  );
  alter table hr_payslips enable trigger hr_payslips_no_delete;
  alter table hr_payroll_runs enable trigger hr_payroll_runs_no_delete;
  delete from hr_shifts where name = 'وردية المطبخ الصباحية';
  delete from hr_employees where employee_code in ('EMP-001', 'EMP-002', 'EMP-003');
  get diagnostics removed = row_count;
  update items set is_active = false
  where sku ilike 'DEMO%' or name ilike 'DEMO%' or name like 'أثير%';
  update warehouses set status = 'inactive'
  where code = 'DEMO-MAIN' or name ilike 'DEMO%' or name like 'أثير%';
  update customers set status = 'blocked'
  where status <> 'blocked' and (name ilike 'DEMO%' or name like 'أثير%');
  return removed;
end;
$$;
revoke all on function erp_purge_demo_placeholders() from public, anon, authenticated;

select erp_purge_demo_placeholders();

