insert into hr_payroll_runs (tenant_id, period, gross_minor, deductions_minor, net_minor, status, created_by)
select tenant.id, run.period, run.gross, 0, run.gross, 'draft', tenant.created_by
from tenants as tenant
join (values
  ('2026-10', 380750::bigint),
  ('2026-09', 29281950::bigint),
  ('2026-08', 30253250::bigint),
  ('2026-07', 28323750::bigint),
  ('2026-06', 29834250::bigint),
  ('2026-05', 30904050::bigint),
  ('2026-04', 31045950::bigint),
  ('2026-03', 15594600::bigint)
) as run(period, gross) on true
where exists (select 1 from hr_employees as employee where employee.tenant_id = tenant.id and employee.employee_code = 'O1')
  and not exists (
    select 1 from hr_payroll_runs as existing where existing.tenant_id = tenant.id and existing.period = run.period
  );

