join hr_employees as employee on employee.tenant_id = tenant.id and employee.employee_code = slip.code
join hr_payroll_runs as run on run.tenant_id = tenant.id and run.period = slip.period and run.status = 'draft'
where not exists (
  select 1 from hr_payslips as existing
  where existing.tenant_id = tenant.id and existing.run_id = run.id and existing.employee_id = employee.id
);

insert into hr_attendances (tenant_id, employee_id, check_in, check_out, overtime_minutes, created_by)
select tenant.id, employee.id, stamp.check_in, stamp.check_out, 0, tenant.created_by
from tenants as tenant
