join hr_employees as employee on employee.tenant_id = tenant.id and employee.employee_code = stamp.code
where not exists (
  select 1 from hr_attendances as existing
  where existing.tenant_id = tenant.id and existing.employee_id = employee.id and existing.check_in = stamp.check_in
);

