) as request(code, leave_type, start_date, end_date, days, approval_status) on true
join hr_employees as employee on employee.tenant_id = tenant.id and employee.employee_code = request.code
where not exists (
  select 1 from hr_leaves as existing
  where existing.tenant_id = tenant.id and existing.employee_id = employee.id
    and existing.start_date = request.start_date and existing.leave_type = request.leave_type
);

