join hr_employees as employee on employee.tenant_id = tenant.id and employee.employee_code = claim.code
where not exists (
  select 1 from hr_expenses as existing
  where existing.tenant_id = tenant.id and existing.employee_id = employee.id and existing.category = claim.category and existing.amount_minor = claim.amount
);

